  //    另外一直带一小段「正文里有人要发叮叮」的写法（<!--叮叮 名字：消息-->，见 §6c），「正文里的人主动来消息」开关关了才不带
  function blockedOf(id, s) { var b = (dd(s).bl || {})[id]; return b && b.on ? b : null; }
