        var bb = DOC.createElement('div'); bb.className = 'bb';
        var sk = String(row.text).match(/^［表情包：(.+?)］$|^\[表情包：(.+?)\]$/), skn = sk ? resolveSticker(sk[1] || sk[2]) : '';
        if (skn) { bb.className = 'bb stk'; bb.innerHTML = stickerImg(skn); } else bb.textContent = row.text;
