  //   返回 Promise<{ ok, who: [实际来消息的人], why? }>
  function notifyEvent(kind, payload) {
    payload = payload || {};
    var K = EVENT_KINDS[kind] || EVENT_KINDS.other, text = String(payload.text || '').trim();
    if (!C) return Promise.resolve({ ok: false, who: [], why: '叮叮没起来' });
    if (!text && !K.head) return Promise.resolve({ ok: false, who: [], why: '没写发生了什么' });
    var now = Date.now();
    if (!payload.force && _evAt[kind] && now - _evAt[kind] < K.cool * 1000) return Promise.resolve({ ok: false, who: [], why: '冷却中' });
    if (_evPending >= 3) return Promise.resolve({ ok: false, who: [], why: '排队太多' });
    _evAt[kind] = now; _evPending++;
    var run = function () {
      return (async function () {
        var s = st(), d = dd(s);
        if (!isOn('auto')) return { ok: false, who: [], why: '主动来消息关着' };
        if (!hasIdentity(s)) return { ok: false, who: [], why: '还没选身份' };
        if (payload.key && (d.evk || []).indexOf(String(payload.key)) >= 0) return { ok: false, who: [], why: '这件事发过了' };
        var want = [].concat(payload.who || []).concat(payload.who && payload.who.length ? [] : K.who), cs = [];
        for (var i = 0; i < want.length && cs.length < (payload.max || K.max); i++) {
          var c = await chatForName(want[i], s);
          if (c && !c.group && !blockedOf(c.id, s) && !cs.some(function (x) { return x.id === c.id; })) cs.push(c);
        }
        if (!cs.length) return { ok: false, who: [], why: '找不到该来消息的人' };
        var known = contacts(s).map(function (x) { return x.id; });
        await C.save(function (s2) {
          s2.dd.evk = (s2.dd.evk || []).concat(payload.key ? [String(payload.key)] : []).slice(-40);
          cs.forEach(function (c) { if (known.indexOf(c.id) < 0) addContact(s2, c.id, { name: c.name, kind: 'free', sub: '圈里的人' }); });
        });
        var why = (K.head ? K.head + (text ? '：' : '。') : '') + text + (/[。！？]$/.test(text) ? '' : (text ? '。' : '')) +
          '这件事' + cs.map(function (c) { return c.name; }).join('、') + '知道（' + (kind === 'hurt' ? '受委屈的就是' + cs[0].name + '自己' : '消息是行里、公司里传开的，或者本人就在场') + '），现在在' + APP + '上跟' + uc(s) + '说这件事：说法、情绪按各自的人设和跟' + uc(s) + '的关系来。';
        var before = {}; cs.forEach(function (c) { before[c.id] = (dd().h[c.id] || []).length; });
        _bgBusy = true;
        try { await replyBatch(cs.map(function (c) { return c.id; }), false, { initiate: true, bg: true, reason: why }); } finally { _bgBusy = false; }
        var got = cs.filter(function (c) { return (dd().h[c.id] || []).length > before[c.id]; }).map(function (c) { return c.name; });
        return { ok: got.length > 0, who: got };
      })();
    };
    var p = _evQ.then(function () { return new Promise(function (r) { setTimeout(r, 0); }); }).then(run);
    _evQ = p.catch(function () {}).then(function () { _evPending = Math.max(0, _evPending - 1); });
    return p.catch(function (e) { return { ok: false, who: [], why: (e && e.message) || String(e) }; });
  }

