  var DEF_PRICE = { '全年龄': 2000, 'R15': 3000, 'R18 常见XP': 5000, 'R18 BDSM': 6000, '深渊': 8000 };   // 人民币（10-23）；服务器 pc_config 的区间要跟着改成 1000–50000
  var FIELD = { name: '名字', title: '片名', blurb: '卖点', film_no: '番号', tags: '标签', cast: '卡司', script: '剧本正文', comment: '评价', text: '这段字' };
