    if (!f) scr = '<button class="pl-poster" data-act="ol-pl-play" aria-label="播放">' + (PL.end && PL.end.cover || '') + '<span class="pl-big">▶</span>' + (PL.pv ? '<span class="pl-pvtag">预告</span>' : '') + '</button>';
