    var tot = plTotal(), at = Math.min(tot, plUpTo(Math.max(0, i + 1))), pc = tot ? Math.round(at / tot * 1000) / 10 : 0;
    var ticks = fr.map(function (x, k) { return x.k === 'scene' ? '<i style="left:' + (tot ? Math.round(plUpTo(k) / tot * 1000) / 10 : 0) + '%"></i>' : ''; }).join('');
