    var old = (byName[USER_WB['导演']] || byName[USER_WB['男优']]) && !byName[USER_WB['社长']] ? book : '';
    if (old !== WB.old) { WB.old = old; try { ensureBoard(); } catch (e) {} }   // 公告栏「自己开公司」那张跟着挂提醒
    if (want === USER_WB['社长'] && old) return wbFail(oldWbMsg(old), loud);
