      if (!scs.some(function (x) { return x && x.name === '自动更新角色卡'; })) return null;   // 只管在线版（离线版不走更新器，也不该拉在线版的卡）
      var me = scs.some(function (x) { return x && /PIANCHANG_CORE|pianchang_script_ref/.test(String(x.content || '')); });
