      out.push('月初：写字楼和剪辑室 ' + money(-bill.office) + '，工资 ' + money(-bill.pay) + (lr ? '，还贷 ' + money(-(lr.bill.principal + lr.bill.interest)) : ''));
      if (lr && lr.overdue) out.push('⚠ ' + C.pick((L.banker && L.banker.toasts) || ['这个月的分期没扣够，罚息记上了。']));
